"""Notably, every subgroup of $S_7$ generated by two $7$-cycles is either a cyclic group of order $7$, the group $PSL(2,7)$ we want, or all of $S_7$."""

import json


def cycle_permutation(cycle):
    permutation = list(range(7))
    for index in range(len(cycle)):
        permutation[cycle[index]] = cycle[(index + 1) % len(cycle)]
    return tuple(permutation)


def compose(left, right):
    return tuple(left[right[index]] for index in range(7))


def inverse(permutation):
    result = [0] * 7
    for index, image in enumerate(permutation):
        result[image] = index
    return tuple(result)


def generated_subgroup(first, second):
    identity = tuple(range(7))
    generators = (first, second, inverse(first), inverse(second))
    elements = [identity]
    seen = {identity}
    position = 0
    while position < len(elements):
        current = elements[position]
        position += 1
        for generator in generators:
            product = compose(generator, current)
            if product not in seen:
                seen.add(product)
                elements.append(product)
    return seen


a = cycle_permutation((0, 1, 2, 3, 4, 5, 6))
b = cycle_permutation((0, 1, 2, 3, 4, 6, 5))
search_space_candidates = ((a, b),)
witness = None
for first, second in search_space_candidates:
    subgroup = generated_subgroup(first, second)
    if len(subgroup) not in (7, 168, 5040):
        witness = (first, second, len(subgroup))

assert witness is not None
assert witness[2] == 2520

result = {
    "record_id": "mse_4689312__ans4689344",
    "outcome": "WITNESS_FOUND",
    "witness_description": "In S_7 on {0,...,6}, let a=(0 1 2 3 4 5 6) and b=(0 1 2 3 4 6 5). The exact closure <a,b> has 2520 elements.",
    "refutation_explanation": "The three claimed possibilities have orders 7, 168, and 5040, respectively, whereas <a,b> has order 2520. Thus this subgroup is none of the listed possibilities, so the universal claim is false.",
    "search_space": "The singleton bounded space consisting of the ordered pair (a,b), with a=(0 1 2 3 4 5 6) and b=(0 1 2 3 4 6 5), was swept exhaustively. Its subgroup closure was computed exactly by deterministic breadth-first enumeration."
}
print(json.dumps(result))
